BEGIN;
-- P6-05 (ADR 0065): one reviewed CHECK replacement on "SocialNotice" adding the Social Goal kinds.
-- Goal notices use the existing Group or Activity context column, so the context CHECK and every
-- existing row are unchanged; the LOAN_/CLAIM_ context ties are preserved verbatim.
ALTER TABLE "SocialNotice" DROP CONSTRAINT "SocialNotice_kind_check";
ALTER TABLE "SocialNotice" ADD CONSTRAINT "SocialNotice_kind_check" CHECK ("kind" IN ('ACTIVITY_INVITED','ACTIVITY_UPDATED','ACTIVITY_CANCELED','ACTIVITY_REMOVED','SEAT_OFFERED','ACTIVITY_REMINDER','EXPENSE_PROPOSED','EXPENSE_DECIDED','SETTLEMENT_RECORDED','SETTLEMENT_DECIDED','ORGANIZER_NOMINATED','ACTIVITY_DELETED','LOAN_REQUESTED','LOAN_OFFERED','LOAN_DECIDED','LOAN_HANDOVER','LOAN_RECEIVED','LOAN_RETURN_REQUESTED','LOAN_RETURNED','LOAN_DISPUTED','LOAN_OUTCOME_PROPOSED','LOAN_OUTCOME_CONFIRMED','LOAN_DUE_PROPOSED','LOAN_DUE_DECIDED','CLAIM_SUBMITTED','CLAIM_DECIDED','CLAIM_HANDOVER','CLAIM_RESOLVED','CLAIM_DISPUTED','GOAL_ENTRY_SUBMITTED','GOAL_ENTRY_DECIDED','GOAL_CORRECTED','GOAL_COMPLETED','GOAL_ENDED') AND ((("loanId" IS NOT NULL) = ("kind" LIKE 'LOAN\_%')) AND (("lostFoundReportId" IS NOT NULL) = ("kind" LIKE 'CLAIM\_%'))));
COMMIT;
